'use strict';
const D=window.STUDY_DATA,S=window.StudyState,KEY='lokesh-ssc-je-v1';
const main=document.getElementById('main');
const byId=Object.fromEntries(D.chapters.map(c=>[c.id,c]));
const subjectById=Object.fromEntries(D.subjects.map(s=>[s.id,s]));
const sourceById=Object.fromEntries(D.sources.map(s=>[s.id,s]));
const practice=D.chapters.flatMap(c=>c.practice),models=D.chapters.flatMap(c=>c.models);
let state=S.fresh(),storageOK=true,toastTimer,page=1,filterSubject='all',filterSource='all',filterSaved=false;
try{const raw=localStorage.getItem(KEY);if(raw)state=S.clean(JSON.parse(raw),D)}catch{storageOK=false;}
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const setToggle=(arr,id)=>arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Browser storage is unavailable. Export a backup before closing.');}updateSidebar();}
function toast(t){const n=document.getElementById('toast');n.textContent=t;n.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('visible'),4500);}
function route(){return (location.hash.slice(1)||'syllabus').split('/');}
function head(eyebrow,title,desc,extra=''){return `<div class="page-head"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(desc)}</p></div>${extra}</div>`;}
function empty(title,desc){return `<div class="empty"><h3>${e(title)}</h3><p>${e(desc)}</p><a class="button" href="#subjects">Browse subjects →</a></div>`;}
function updateSidebar(){document.getElementById('side-progress').style.width=(state.complete.length/D.chapters.length*100)+'%';document.getElementById('side-complete').textContent=`${state.complete.length} of ${D.chapters.length} chapters completed`;document.getElementById('review-count').textContent=S.mistakes(state,D).length;const total=document.getElementById('overview-complete');if(total)total.textContent=`${state.complete.length} of ${D.chapters.length} completed`;let r=route()[0];if(['chapter','subject'].includes(r))r='subjects';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===r);if(a.dataset.nav===r)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function stats(){return `<div class="stats"><div class="stat"><strong>${state.complete.length}/${D.chapters.length}</strong><small>chapters completed</small></div><div class="stat"><strong>${D.pyqs.length}</strong><small>sourced PYQ concepts</small></div><div class="stat"><strong>${models.length}</strong><small>worked models</small></div><div class="stat"><strong>${practice.length}</strong><small>original practice questions</small></div></div>`;}
function syllabus(){
 const sections=D.subjects.map(s=>{const cs=D.chapters.filter(c=>c.subject===s.id),n=cs.filter(c=>state.complete.includes(c.id)).length;return `<details class="card syllabus-card" ${s.id==='machines'?'open':''}><summary><span class="subject-number">${s.icon}</span><span><strong>${e(s.name)}</strong><small>${n}/${cs.length} completed · ${cs.length} chapters</small></span><span class="chevron">›</span></summary><div class="syllabus-items">${cs.map(c=>`<div class="syllabus-item"><input type="checkbox" data-complete="${c.id}" ${state.complete.includes(c.id)?'checked':''} aria-label="Mark ${e(c.title)} complete"><a href="#chapter/${c.id}/notes">${e(c.title)}</a><span class="small-status">${c.minutes} min read ↗</span></div>`).join('')}<a class="text-link" href="#subject/${s.id}">Open ${e(s.short)} →</a></div></details>`}).join('');
 return head('YOUR STUDY DESK / 2026','Your syllabus. Your next step.','A focused space for your SSC JE Electrical preparation. Start with a chapter, work the questions, and mark what you can recall.',`<a href="#chapter/transformers/notes" class="button primary">Start transformers ↗</a>`)+
 `<div class="source-strip"><a href="${e(sourceById.ssc2026.url)}" target="_blank" rel="noopener">Official SSC syllabus ↗</a><span>2026 notification · §14.2.3.1 and §14.3.2 · The chapter grouping below is your study map.</span></div><div class="section-label"><h2>01 / Your electrical syllabus</h2><p id="overview-complete">${state.complete.length} of ${D.chapters.length} completed</p></div><div class="grid">${sections}</div><p class="coverage">Notes cover all seven electrical groups. PYQs are a selected, traceable sample; <a class="text-link" href="#sources">see coverage and source limits</a>.</p>
 <div class="grid nontech">${D.nontechnical.map(s=>`<section class="card"><div class="tiny-label">PAPER I · NON-TECHNICAL SYLLABUS</div><h3>${e(s.title)}</h3>${s.topics.map((t,i)=>`<label><input type="checkbox" data-nontech="${s.id}-${i}" ${state.nontechnical.includes(s.id+'-'+i)?'checked':''}>${e(t)}</label>`).join('')}<p class="fineprint">Syllabus checklist. The chapter notes and practice library currently focus on Electrical.</p></section>`).join('')}</div>
 <div class="section-label"><h2>02 / The date you’re working towards</h2></div><section class="card countdown"><div><div class="tiny-label">YOUR PERSONAL TARGET</div><h2>30 October 2026</h2><p>Countdown to midnight in India (IST).<br>This is your target, not an official exam-date announcement.</p></div><div class="clock" id="clock" aria-label="Time remaining"></div></section>
 <div class="section-label"><h2>03 / Your weekly schedule</h2></div><section class="card schedule"><span class="schedule-mark" aria-hidden="true">▦</span><div><h3>Waiting for your schedule photo.</h3><p>Your goal: complete Electrical in seven days. I’ll add your weekly plan when you send it.</p></div><span class="tag warm">Not added yet</span></section>
 <div class="section-label"><h2>04 / Keep your revision moving</h2></div>${stats()}<div class="actions"><a href="#subjects" class="button primary">Open subject library →</a><a href="#review" class="button">Review mistakes</a><a href="#downloads" class="button">Download notes ↓</a></div><p class="fineprint">Your progress stays in this browser. Use the backup controls in Downloads to keep a copy or move devices.</p>`;
}
function subjectCard(s){let cs=D.chapters.filter(c=>c.subject===s.id);return `<a class="card subject-card" href="#subject/${s.id}"><span class="subject-number">${s.icon}</span><h2>${e(s.name)}</h2><p>${e(s.description)}</p><div class="card-foot"><span>${cs.length} chapters · ${cs.filter(c=>state.complete.includes(c.id)).length} completed</span><span>Open subject ↗</span></div></a>`;}
function subjects(){return head('SUBJECT LIBRARY','Make the concepts yours.','Choose a subject, then a chapter. Every chapter has notes, worked models and original practice.')+stats()+`<div class="grid subjects-grid">${D.subjects.map(subjectCard).join('')}</div>`;}
function chapterCard(c){const saved=state.saved.includes(c.id),n=D.pyqs.filter(q=>q.chapter===c.id).length;return `<article class="card chapter-card"><div class="meta"><span class="tag">${state.complete.includes(c.id)?'Completed':'Ready to study'}</span><span>${c.minutes} min read</span></div><h3><a href="#chapter/${c.id}/notes">${e(c.title)}</a></h3><p>${e(c.summary)}</p><div class="meta">${c.models.length} models · ${c.practice.length} practice · ${n} PYQ concepts</div><div class="actions" style="margin-top:18px"><a class="button primary" href="#chapter/${c.id}/notes">Read chapter →</a><button class="button saved-button" data-save="${c.id}" aria-pressed="${saved}">${saved?'★ Saved':'☆ Save'}</button></div></article>`;}
function subject(id){const s=subjectById[id];if(!s)return empty('Subject not found','Choose a subject from the library.');return `<div class="breadcrumb"><a href="#subjects">Subject library</a><span>/</span><span>${e(s.short)}</span></div>`+head(`SUBJECT ${s.icon}`,s.name,s.description)+`<div class="grid">${D.chapters.filter(c=>c.subject===id).map(chapterCard).join('')}</div>`;}
function modelCard(m){const ev=S.evidence(m.tag,D);return `<article class="card model-card"><div class="q-meta"><span class="tag">Original worked model</span></div><h3 style="margin-top:12px">${e(m.title)}</h3><p>${e(m.prompt)}</p><details><summary>Show method</summary><div class="solution">${e(m.solution)}</div></details><div class="evidence">${ev.papers>=2?`Related concept appears in ${ev.papers} collected papers.`:ev.questions.length?`${ev.questions.length} related example${ev.questions.length===1?'':'s'} in the collected bank.`:'No matched sourced PYQ in this bank yet; this is syllabus practice.'}${ev.questions.map(q=>`<a href="#question/${q.id}">${e(sourceById[q.source].title.split(' · ').slice(0,2).join(' · '))} Q${q.q}</a>`).join('')}</div></article>`;}
function pyqCard(q){const c=byId[q.chapter],source=sourceById[q.source],s=state.pyqStatus[q.id];return `<article class="card question-card" id="q-${q.id}"><div class="q-meta"><span class="tag">PYQ · paraphrased concept</span><a href="#chapter/${c.id}/notes">${e(c.title)} ↗</a>${s?`<span class="tag ${s==='revise'?'warm':''}">${s==='right'?'Understood':'To revise'}</span>`:''}</div><h3>${e(q.prompt)}</h3><div class="q-meta"><a class="text-link" href="${e(source.url)}#page=${q.page}" target="_blank" rel="noopener">${e(source.title)} · Q${q.q} · PDF p.${q.page} ↗</a></div><details><summary>Reveal independently worked answer</summary><div class="solution">${e(q.answer)}</div></details><div class="actions"><button class="button small" data-pyq="${q.id}" data-status="right">✓ Understood</button><button class="button small" data-pyq="${q.id}" data-status="revise">Revisit this</button></div></article>`;}
function practiceCard(q){const a=state.answers[q.id],done=Number.isInteger(a),correct=a===q.answer;return `<article class="card question-card" id="q-${q.id}"><div class="q-meta"><span class="tag">Original practice · not a PYQ</span><a href="#chapter/${q.chapter}/notes">${e(byId[q.chapter].title)} ↗</a></div><h3>${e(q.prompt)}</h3><div class="options">${q.options.map((o,i)=>`<button class="option ${done&&i===q.answer?'correct':''} ${done&&i===a&&!correct?'wrong':''}" data-answer="${q.id}" data-option="${i}" ${done?'disabled':''}><span>${'ABCD'[i]}</span>${e(o)}${done&&i===q.answer?' ✓':''}${done&&i===a&&!correct?' ✕':''}</button>`).join('')}</div>${done?`<div class="result-line ${correct?'':'wrong'}"><strong>${correct?'Correct.':'Review this concept.'}</strong><p>${e(q.explanation)}</p></div><div class="actions"><button class="button small" data-retry="${q.id}">Try again</button><a class="button small" href="#chapter/${q.chapter}/notes">Revisit the notes</a></div>`:''}</article>`;}
const diagramCaptions={transformer:'Ideal two-winding transformer · shared core flux · a = N₁/N₂',induction:'Induction-motor power flow · separate rotor copper and mechanical losses',rc:'First-order RC charging · capacitor voltage remains continuous',phasor:'Series R–L phasors · resistor voltage horizontal; inductor voltage leads current',buck:'Ideal buck converter · switch ON and OFF energy paths'};
function chapterPage(id,tab='notes'){const c=byId[id];if(!c)return empty('Chapter not found','Open the chapter from the subject library.');if(!['notes','pyqs','models','practice'].includes(tab))tab='notes';const qs=D.pyqs.filter(q=>q.chapter===id);let body='';
 if(tab==='notes')body=`<div class="reader-layout"><article class="reader">${c.diagram?`<figure class="diagram"><img src="assets/${c.diagram}.svg" alt="${e(diagramCaptions[c.diagram])}"><figcaption>${e(diagramCaptions[c.diagram])}</figcaption></figure>`:''}${c.html}<div class="reader-footer"><label class="check-row"><input type="checkbox" data-complete="${id}" ${state.complete.includes(id)?'checked':''}>Mark chapter complete</label><a class="button primary" href="#chapter/${id}/practice">Test your recall →</a></div><h2>My chapter notes</h2><label class="sr-only" for="personal-notes">Personal notes for ${e(c.title)}</label><textarea class="note-area" id="personal-notes" data-notes="${id}" placeholder="A formula you forgot, a doubt to revisit…">${e(state.notes[id]||'')}</textarea><p class="helper">Saves as you type on this browser. Included in your progress backup.</p></article><aside class="toc"><strong>IN THIS CHAPTER</strong>${c.headings.map(h=>`<button data-scroll="${h.anchor}">${e(h.title)}</button>`).join('')}<a class="text-link" href="notes/${id}.md" download>Download chapter (.md) ↓</a><p class="fineprint">Original teaching notes. Sources & coverage lists the official syllabus and separate PYQ references.</p></aside></div>`;
 if(tab==='pyqs')body=`<p class="helper">Selected concepts from paper reproductions, with independently worked answers. Question wording is paraphrased and original options are omitted.</p><div class="question-list">${qs.length?qs.map(pyqCard).join(''):empty('No matched PYQ added here yet.','Use the original models and practice for this chapter. The source-paper library remains available for further questions.')}</div><p class="fineprint"><a class="text-link" href="#sources">Open the complete paper sources ↗</a></p>`;
 if(tab==='models')body=`<p class="helper">Worked examples are original. Evidence links show related concepts in the collected PYQs, not a predicted frequency in your exam.</p><div class="grid">${c.models.map(modelCard).join('')}</div>`;
 if(tab==='practice')body=`<p class="helper">Original questions with immediate explanations. Incorrect answers join your revision list.</p><div class="question-list">${c.practice.map(practiceCard).join('')}</div>`;
 return `<div class="breadcrumb"><a href="#subjects">Subjects</a><span>/</span><a href="#subject/${c.subject}">${e(subjectById[c.subject].short)}</a><span>/</span><span>${e(c.title)}</span></div>`+head('CHAPTER NOTES',c.title,c.summary,`<div class="actions"><button class="button saved-button" data-save="${id}" aria-pressed="${state.saved.includes(id)}">${state.saved.includes(id)?'★ Saved':'☆ Save'}</button><button class="button" data-print>Print / PDF</button><a class="button" download href="notes/${id}.md">Download ↓</a></div>`)+`<nav class="chapter-tabs" aria-label="Chapter sections">${[['notes','One-shot notes'],['pyqs',`PYQs (${qs.length})`],['models',`Models (${c.models.length})`],['practice',`Practice (${c.practice.length})`]].map(([t,label])=>`<a class="${t===tab?'active':''}" href="#chapter/${id}/${t}" ${t===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`+body;
}
function filterbar(kind,count){return `<div class="filterbar"><label>Subject <select id="subject-filter"><option value="all">All electrical subjects</option>${D.subjects.map(s=>`<option value="${s.id}" ${filterSubject===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></label>${kind==='pyqs'?`<label>Paper <select id="source-filter"><option value="all">All collected papers</option>${D.sources.filter(s=>s.kind==='Paper reproduction').map(s=>`<option value="${s.id}" ${filterSource===s.id?'selected':''}>${e(s.title)}</option>`).join('')}</select></label>`:''}<span class="filter-count">${count} results</span></div>`;}
function paginate(arr,renderItem){let size=8,max=Math.max(1,Math.ceil(arr.length/size));page=Math.min(page,max);return `<div class="question-list">${arr.slice((page-1)*size,page*size).map(renderItem).join('')||empty('No questions in this selection','Try another subject or paper.')}</div>${max>1?`<div class="pager"><button class="button small" data-page="${page-1}" ${page<=1?'disabled':''}>← Previous</button><span>Page ${page} of ${max}</span><button class="button small" data-page="${page+1}" ${page>=max?'disabled':''}>Next →</button></div>`:''}`;}
function bank(kind){let arr=kind==='pyqs'?D.pyqs:kind==='models'?models:practice;arr=arr.filter(q=>filterSubject==='all'||byId[q.chapter].subject===filterSubject);if(kind==='pyqs')arr=arr.filter(q=>filterSource==='all'||q.source===filterSource);const labels={pyqs:['PREVIOUS QUESTIONS','Learn the question behind the question.',`${D.pyqs.length} selected PYQ concepts from six papers. Source links and question numbers stay beside every item.`],models:['QUESTION MODELS','Recognise the method.','Original worked models, linked to related PYQ evidence where available. Counts refer only to this collected sample.'],practice:['ACTIVE RECALL','Try it before looking.','Original Electrical practice questions. Pick an answer to see the method and build your revision list.']};let extra='';if(kind==='practice'){const score=S.score(state,arr);extra=`<div class="source-strip" id="practice-score"><span>${score.attempted}/${arr.length} attempted · ${score.correct} correct · ${score.wrong} to review · ${score.marks.toFixed(2)} practice marks using +1/−0.25. This is a practice bank, not a timed full mock.</span></div>`;}return head(...labels[kind])+extra+filterbar(kind,arr.length)+paginate(arr,kind==='pyqs'?pyqCard:kind==='models'?modelCard:practiceCard);}
function review(){const ids=new Set(S.mistakes(state,D));const qs=practice.filter(q=>ids.has(q.id)),pq=D.pyqs.filter(q=>ids.has(q.id));return head('MY REVISION LIST','Turn a miss into a mark.','Incorrect practice answers and PYQs you marked to revisit appear here. A correct retry clears an original question; mark a PYQ understood when ready.')+`<div class="section-label"><h2>Questions to revisit</h2><p>${ids.size} items</p></div><div class="question-list">${ids.size?qs.map(practiceCard).join('')+pq.map(pyqCard).join(''):empty('A clean revision list.','Start a chapter practice set. Missed questions will collect here.')}</div><div class="section-label"><h2>Saved chapters</h2><p>${state.saved.length} saved</p></div><div class="grid">${state.saved.map(id=>chapterCard(byId[id])).join('')||'<p class="muted">Use ☆ Save on any chapter to keep it here.</p>'}</div>`;}
function downloads(){return head('TAKE YOUR NOTES WITH YOU','Read here. Keep a copy.','Download the chapter collection, revisit your earlier circuit PDFs, or back up your personal progress.')+`<div class="grid"><article class="card download-card"><span class="filetype">ZIP · EDITABLE MARKDOWN</span><h3>All 26 chapter notes</h3><p>One file per chapter, with original worked models and practice answers. Equations are preserved as LaTeX.</p><a class="button primary" href="materials/ssc-je-chapter-notes.zip" download>Download chapter collection ↓</a></article><article class="card download-card"><span class="filetype">PDF · 78 PAGES</span><h3>Circuit Theory · master notes</h3><p>Your existing in-depth circuit handbook, with equations, diagrams and worked material. Its own source notes are included.</p><a class="button primary" href="materials/circuit-theory-master.pdf" download>Download master PDF ↓</a></article><article class="card download-card"><span class="filetype">PDF · 51 PAGES</span><h3>Basic Electrical · companion</h3><p>Your earlier circuit notes, retained as supplementary material. The website chapters provide the current navigation.</p><a class="button" href="materials/circuits-companion.pdf" download>Download companion ↓</a></article><article class="card download-card"><span class="filetype">PRINTABLE CHAPTERS</span><h3>Make a chapter PDF</h3><p>Open a chapter’s notes, choose Print / PDF, then save as PDF in your browser. The print layout removes navigation.</p><a class="button" href="#chapter/transformers/notes">Open Transformers →</a></article></div><section class="card backup-panel"><h2>Your progress backup</h2><p>Completion marks, bookmarks, practice answers, revision items and personal chapter notes save on this browser only. Export a JSON backup before clearing browser data or changing devices. Import replaces the current local progress after validation.</p><div class="actions"><button class="button primary" data-export>Export my progress ↓</button><button class="button" data-import>Import backup ↑</button><a class="button" href="materials/ssc-je-website-source.zip" download>Download website source ↓</a></div><p class="helper">${storageOK?'Browser storage is available.':'Browser storage is unavailable; keep an exported backup.'} No personal progress is uploaded to GitHub.</p></section>`;}
function sources(){return head('SOURCES & COVERAGE','Clear notes. Traceable questions.','Official syllabus, paper reproductions and the limits of this study collection.')+`<div class="card"><h2>What is included</h2><p>26 Electrical chapters, 63 original worked models, 79 original practice questions and 44 short, independently solved PYQ concepts. Six paper reproductions supply the current PYQ sample. This is not a complete transcription of those papers or of all SSC JE shifts.</p><p>Some chapters currently have no individually indexed PYQ. The full linked papers let you consult questions beyond this sample. Recurrence labels count related concepts in the collected papers only; they do not claim official weightage, exact repeated wording or future frequency.</p><p>The PDF response sheets may show a candidate’s “Chosen Option”. That is not treated as the correct answer. The website answers are independently worked, and the original answer options are not reproduced. Ambiguous or image-only questions that were not fully inspected are not added as solved items.</p><p>The electrical grouping is a teaching organisation of the 2026 syllabus. Reasoning and General Awareness have syllabus checklists; their full notes are not part of the present Electrical library. The 30 October date is your personal target. Your schedule is awaiting your photo.</p><p class="fineprint">Content edition: ${e(D.edition)}. Original notes are exam study material, not field-work procedures or a claim of official SSC endorsement.</p></div><div class="section-label"><h2>Paper pattern</h2></div><div class="card"><p>Paper I: 50 Reasoning + 50 General Awareness + 100 Electrical questions; 200 marks, 120 minutes. Paper II: 100 Electrical questions; 300 marks, 120 minutes. Wrong answers: −0.25 in Paper I, −1 in Paper II. Eligible candidates may receive the extra time stated in the notification.</p><a class="text-link" href="${e(sourceById.ssc2026.url)}#page=20" target="_blank" rel="noopener">Official notification · §13 ↗</a></div><div class="section-label"><h2>Read the sources</h2></div><div class="grid">${D.sources.map(s=>`<article class="card source-card"><span class="tag">${e(s.kind)}</span><h3 style="margin-top:12px">${e(s.title)}</h3><p>${e(s.detail)}</p><a class="text-link" href="${e(s.url)}" target="_blank" rel="noopener">Open source ↗</a></article>`).join('')}</div>`;}
function searchPage(query){const q=query.toLowerCase().trim(),cs=q?D.chapters.filter(c=>(c.title+' '+c.summary+' '+c.body).toLowerCase().includes(q)):[];const qs=q?D.pyqs.filter(v=>(v.prompt+' '+v.answer+' '+byId[v.chapter].title).toLowerCase().includes(q)):[];return head('SEARCH',q?'Results for “'+query+'”':'Find a concept','Search covers chapter text and indexed PYQ concepts.')+`<div class="section-label"><h2>Chapters</h2><p>${cs.length} matches</p></div><div class="grid">${cs.map(chapterCard).join('')}</div><div class="section-label"><h2>PYQ concepts</h2><p>${qs.length} matches</p></div><div class="question-list">${qs.map(pyqCard).join('')}</div>${!cs.length&&!qs.length?empty('No matching content','Try a broader term such as flux, resonance or rectifier.'):''}`;}
function render(focus=false){let [r,id,tab]=route(),content;switch(r){case 'syllabus':content=syllabus();break;case 'subjects':content=subjects();break;case 'subject':content=subject(id);break;case 'chapter':content=chapterPage(id,tab);break;case 'pyqs':case 'models':case 'practice':content=bank(r);break;case 'review':content=review();break;case 'downloads':content=downloads();break;case 'sources':content=sources();break;case 'question':{const q=D.pyqs.find(q=>q.id===id);content=q?head('SOURCED QUESTION','One concept, worked through.','A selected PYQ paraphrase with its source paper.')+pyqCard(q):empty('Question not found','Open a question from the bank.');break;}case 'search':{let query='';try{query=decodeURIComponent(id||'')}catch{}content=searchPage(query);break;}default:content=empty('Page not found','Use the navigation to return to your study desk.');}
 main.innerHTML=content;updateSidebar();updateClock();if(focus){window.scrollTo(0,0);main.focus({preventScroll:true});}document.title=(r==='chapter'&&byId[id]?byId[id].title+' · ':'')+'Lokesh’s Study Desk · SSC JE';}
function updateClock(){const n=document.getElementById('clock');if(!n)return;const t=S.countdown(Date.now());n.innerHTML=t.finished?'<div><strong>Target day</strong><small>Keep your revision moving</small></div>':[['days','Days'],['hours','Hours'],['minutes','Minutes'],['seconds','Seconds']].map(([k,l])=>`<div><strong>${String(t[k]).padStart(2,'0')}</strong><small>${l}</small></div>`).join('');}
function refreshScore(){const n=document.getElementById('practice-score');if(n){const qs=practice.filter(q=>filterSubject==='all'||byId[q.chapter].subject===filterSubject),v=S.score(state,qs);n.textContent=`${v.attempted}/${qs.length} attempted · ${v.correct} correct · ${v.wrong} to review · ${v.marks.toFixed(2)} practice marks using +1/−0.25. This is a practice bank, not a timed full mock.`;}}
function replaceQuestion(id){const n=document.getElementById('q-'+id),q=practice.find(q=>q.id===id);if(n&&q)n.outerHTML=practiceCard(q);}
document.addEventListener('click',ev=>{
 const b=ev.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-save')){const id=b.dataset.save;state.saved=setToggle(state.saved,id);persist();b.setAttribute('aria-pressed',state.saved.includes(id));b.textContent=state.saved.includes(id)?'★ Saved':'☆ Save';toast(state.saved.includes(id)?'Chapter saved to your revision list.':'Chapter removed from saved items.');}
 if(b.dataset.answer){const q=practice.find(q=>q.id===b.dataset.answer),a=Number(b.dataset.option);if(q&&!Object.hasOwn(state.answers,q.id)){state.answers[q.id]=a;persist();if(route()[0]==='practice'||route()[0]==='review')render();else replaceQuestion(q.id);}}
 if(b.dataset.retry){delete state.answers[b.dataset.retry];persist();replaceQuestion(b.dataset.retry);refreshScore();toast('Try the question again.');}
 if(b.dataset.pyq){state.pyqStatus[b.dataset.pyq]=b.dataset.status;persist();const n=document.getElementById('q-'+b.dataset.pyq),q=D.pyqs.find(q=>q.id===b.dataset.pyq);if(route()[0]==='review'&&b.dataset.status==='right')render();else if(n&&q)n.outerHTML=pyqCard(q);toast(b.dataset.status==='right'?'Marked understood.':'Added to your revision list.');}
 if(b.dataset.page){page=Number(b.dataset.page);render(true);}
 if(b.dataset.scroll){document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 if(b.hasAttribute('data-print'))window.print();
 if(b.hasAttribute('data-export')){download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'ssc-je-progress.json','application/json');toast('Progress backup downloaded.');}
 if(b.hasAttribute('data-import'))document.getElementById('backup-file').click();
});
document.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.complete){state.complete=setToggle(state.complete,t.dataset.complete);persist();toast(t.checked?'Chapter marked complete.':'Chapter marked for further study.');if(route()[0]==='syllabus'){const details=t.closest('details');const cs=D.chapters.filter(c=>c.subject===byId[t.dataset.complete].subject);details.querySelector('summary small').textContent=`${cs.filter(c=>state.complete.includes(c.id)).length}/${cs.length} completed · ${cs.length} chapters`;}}if(t.dataset.nontech){state.nontechnical=setToggle(state.nontechnical,t.dataset.nontech);persist();}if(t.id==='subject-filter'){filterSubject=t.value;page=1;render();}if(t.id==='source-filter'){filterSource=t.value;page=1;render();}});
document.addEventListener('input',ev=>{if(ev.target.dataset.notes){state.notes[ev.target.dataset.notes]=ev.target.value.slice(0,20000);persist();}});
document.getElementById('search-form').addEventListener('submit',ev=>{ev.preventDefault();const q=document.getElementById('search').value.trim();if(q)location.hash='search/'+encodeURIComponent(q);});
document.getElementById('backup-file').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>2_000_000)throw Error('Backup is too large (maximum 2 MB).');const imported=S.clean(JSON.parse(await f.text()),D);state=imported;persist();render();toast('Backup imported. Your local progress has been replaced.');}catch(err){toast('Import failed: '+err.message);}ev.target.value='';});
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.addEventListener('hashchange',()=>{page=1;render(true);});
render();setInterval(updateClock,1000);if(!storageOK)toast('Could not restore browser progress. Use backups to keep your work.');
